  const counts = new Map();

  for (let i = 0; i <= sequence.length - k; i++) {
    const kmer = sequence.slice(i, i + k);
    counts.set(kmer, (counts.get(kmer) || 0) + 1);
  }

  return counts;
}

function frequencyLines(k) {
  const counts = countKmers(k);
  const total = Math.max(0, sequence.length - k + 1);

  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([kmer, count]) => {
      const percentage = total === 0 ? 0 : (count * 100) / total;
      return `${kmer} ${percentage.toFixed(3)}`;
    });
}

function occurrences(fragment) {
  let count = 0;
  for (let i = 0; i <= sequence.length - fragment.length; i++) {
    if (sequence.startsWith(fragment, i)) count++;
  }
  return count;
}

