function makeTree(depth) {
  if (depth === 0) {
    return { left: null, right: null };
  }

  return {
    left: makeTree(depth - 1),
    right: makeTree(depth - 1)
  };
}

function checkTree(node) {
  if (node.left === null) {
    return 1;
  }

  return 1 + checkTree(node.left) + checkTree(node.right);
