if (hadTrailingNewline) {
  lines.pop();
}

const complement = {
  A: 'T', T: 'A',
  C: 'G', G: 'C',
  U: 'A',
  R: 'Y', Y: 'R',
  K: 'M', M: 'K',
  B: 'V', V: 'B',
  D: 'H', H: 'D',
  S: 'S', W: 'W', N: 'N',
  a: 't', t: 'a',
  c: 'g', g: 'c',
  u: 'a',
  r: 'y', y: 'r',
  k: 'm', m: 'k',
  b: 'v', v: 'b',
  d: 'h', h: 'd',
  s: 's', w: 'w', n: 'n'
};

const output = [];
let header = null;
let sequenceLines = [];

function finishRecord() {
  if (header === null) return;

  const lengths = sequenceLines.map(line => line.length);
  const sequence = sequenceLines.join('');
  const reversed = new Array(sequence.length);

  for (let i = 0, j = sequence.length - 1; j >= 0; i++, j--) {
    const base = sequence[j];
    reversed[i] = complement[base] || base;
  }

  const reverseComplement = reversed.join('');

  output.push(header);

  let offset = 0;
  for (const length of lengths) {
    output.push(reverseComplement.slice(offset, offset + length));
    offset += length;
  }
}

for (const line of lines) {
  if (line.startsWith('>')) {
    finishRecord();
    header = line;
    sequenceLines = [];
  } else if (header !== null) {
    sequenceLines.push(line);
  } else {
    output.push(line);
  }
}

finishRecord();

let result = output.join('\n');
if (hadTrailingNewline) result += '\n';
